const std::array<std::string,3> names{"mac-native","mac-docker","vps-docker"};
const auto began=std::chrono::steady_clock::now();
void check(){if(std::chrono::steady_clock::now()-began>std::chrono::seconds(600))throw std::runtime_error("fresh rotation audit deadline");}
void shape(const Json& j,std::initializer_list<const char*> fields){require(j.is_object()&&j.size()==fields.size(),"fresh document shape");for(auto f:fields)require(j.contains(f),"fresh document missing field");}
uint64_t quantity64(const Json& j){require(j.is_string(),"canonical quantity string required");const auto n=u64(quantity(j));require(quantity(Int(std::to_string(n)))==j.get<std::string>(),"noncanonical quantity");return n;}
std::string q(uint64_t n){return quantity(Int(std::to_string(n)));}
Bytes encoded(const Json& j,size_t width){require(j.is_string(),"hex bytes required");const auto s=j.get<std::string>();require(s.size()==2+2*width,"hex width");auto b=unhex(s);require(b.size()==width&&hex(b)==s,"noncanonical hex");return b;}
ConsensusRoot rvalue(const Json& j){const auto b=encoded(j,32);return root(b);}
ForkCheckpointToken token(const Json& j){shape(j,{"sequence","digest"});const auto n=quantity64(j.at("sequence"));require(n>0,"zero checkpoint");return {n,encoded(j.at("digest"),32)};}
ConsensusCheckpoint cp(const Json& j){shape(j,{"epoch","root"});return {quantity64(j.at("epoch")),rvalue(j.at("root"))};}
bool same(const struct stat&a,const struct stat&b){
#ifdef __APPLE__
 const bool time=a.st_mtimespec.tv_sec==b.st_mtimespec.tv_sec&&a.st_mtimespec.tv_nsec==b.st_mtimespec.tv_nsec&&a.st_ctimespec.tv_sec==b.st_ctimespec.tv_sec&&a.st_ctimespec.tv_nsec==b.st_ctimespec.tv_nsec;
#else
 const bool time=a.st_mtim.tv_sec==b.st_mtim.tv_sec&&a.st_mtim.tv_nsec==b.st_mtim.tv_nsec&&a.st_ctim.tv_sec==b.st_ctim.tv_sec&&a.st_ctim.tv_nsec==b.st_ctim.tv_nsec;
#endif
 return time&&a.st_dev==b.st_dev&&a.st_ino==b.st_ino&&a.st_nlink==b.st_nlink&&a.st_mode==b.st_mode&&a.st_uid==b.st_uid&&a.st_gid==b.st_gid&&a.st_size==b.st_size;
}
void path_guard(const fs::path& p){require(p.is_absolute()&&p==p.lexically_normal(),"absolute normalized path required");fs::path at;for(const auto& leaf:p){at/=leaf;struct stat s{};require(::lstat(at.c_str(),&s)==0&&!S_ISLNK(s.st_mode),"symlink/missing path refused");}}
struct Input {fs::path path;struct stat stamp;std::string bytes;};
std::vector<Input> inputs;
std::string read_known(const fs::path& p,size_t limit){
 check();path_guard(p);const int fd=::open(p.c_str(),O_RDONLY|O_NOFOLLOW|O_NONBLOCK|O_CLOEXEC);require(fd>=0,"input open refused");
 struct Close{int fd;~Close(){::close(fd);}} close{fd};struct stat a{},b{},c{};require(::fstat(fd,&a)==0&&S_ISREG(a.st_mode)&&a.st_nlink==1&&a.st_uid==::geteuid()&&a.st_size>0&&uint64_t(a.st_size)<=limit,"input type/owner/size");
 std::string out(size_t(a.st_size),'\0');size_t at=0;while(at<out.size()){check();const auto n=::read(fd,out.data()+at,out.size()-at);if(n<0&&errno==EINTR)continue;require(n>0,"input truncated");at+=size_t(n);}char extra;require(::read(fd,&extra,1)==0&&::fstat(fd,&b)==0&&::lstat(p.c_str(),&c)==0&&same(a,b)&&same(a,c),"input changed during read");
 const auto prior=std::find_if(inputs.begin(),inputs.end(),[&](const auto& x){return x.path==p;});if(prior!=inputs.end())require(same(prior->stamp,a)&&prior->bytes==out,"previous input changed");else inputs.push_back({p,a,out});return out;
}
Json parse(std::string_view s){std::vector<std::set<std::string>> keys;return Json::parse(s.begin(),s.end(),[&](int depth,Json::parse_event_t event,Json& v){require(depth<=64,"JSON nesting bound");if(event==Json::parse_event_t::object_start)keys.emplace_back();else if(event==Json::parse_event_t::object_end)keys.pop_back();else if(event==Json::parse_event_t::key)require(keys.back().insert(v.get<std::string>()).second,"duplicate JSON field");return true;});}
std::string bound_file(const fs::path& parent,const Json& pin,const char* name,size_t limit){shape(pin,{"path","sha256","bytes"});require(pin.at("path")==name&&pin.at("bytes").is_number_unsigned()&&pin.at("bytes").get<uint64_t>()<=limit,"public file descriptor");const auto s=read_known(parent/name,limit);require(s.size()==pin.at("bytes").get<uint64_t>()&&hex(sha256(Bytes(s.begin(),s.end()))).substr(2)==pin.at("sha256").get<std::string>(),"public file digest differs");return s;}
struct Identity{size_t index,owner;std::string environment;};
using Ownership=std::map<Bytes,Identity>;
