 for(size_t i=0;i<keys.size();++i){check();shape(keys.at(i),{"index","publicKey"});shape(rows.at(i),{"publicKey","keyEnv","owner"});require(keys.at(i).at("index")==i&&rows.at(i).at("publicKey")==keys.at(i).at("publicKey"),"public key order/identity differs");auto key=encoded(keys.at(i).at("publicKey"),48);const auto owner=std::find(names.begin(),names.end(),rows.at(i).at("owner").get<std::string>());const auto env=rows.at(i).at("keyEnv").get<std::string>();require(owner!=names.end()&&!env.empty()&&env.size()<=128&&std::all_of(env.begin(),env.end(),[](unsigned char c){return std::isalnum(c)||c=='_';})&&envs.insert(env).second,"owner/environment authority differs");const auto n=size_t(owner-names.begin());require(result.emplace(std::move(key),Identity{i,n,env}).second,"duplicate public key");++counts[n];}
