size_t committee_offset(const AltairStateLimits& l){require(l.slots_per_historical_root<=UINT32_MAX/64&&l.epochs_per_historical_vector<=UINT32_MAX/32&&l.epochs_per_slashings_vector<=UINT32_MAX/8&&l.sync_committee_size<=(UINT32_MAX/48)-1,"profile layout bound");return 405+64*size_t(l.slots_per_historical_root)+32*size_t(l.epochs_per_historical_vector)+8*size_t(l.epochs_per_slashings_vector);}
