 require(boundary>0&&source_slot<boundary,"boundary source slot refused");
 // prepare_capella_slots requires a STRICT advance. An already authenticated
 // parent at boundary-1 is the required prestate; copy it without an API call.
 if(source_slot==boundary-1)return parent;
